import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.C0KMm31j.js";const s="/Nav2ArticlesSite/article-assets/2026-07-15/nav2_lifecycle_manager_cover.png",c="/Nav2ArticlesSite/article-assets/2026-07-15/01_role_architecture.png",o="/Nav2ArticlesSite/article-assets/2026-07-15/02_initialization_threads.png",l="/Nav2ArticlesSite/article-assets/2026-07-15/03_startup_sequence.png",r="/Nav2ArticlesSite/article-assets/2026-07-15/04_command_matrix.png",p="/Nav2ArticlesSite/article-assets/2026-07-15/05_bond_failure.png",d="/Nav2ArticlesSite/article-assets/2026-07-15/06_respawn_recovery.png",k=JSON.parse('{"title":"Nav2 为什么不会“一窝蜂启动”？拆解 nav2_lifecycle_manager 全数据流","description":"Nav2 里有 mapserver、AMCL、plannerserver、controllerserver、btnavigator 等一批服务器。进程启动，只代表它们进入了 ROS graph；参数是否加载成功、插件是否创建完成、Action 是否可以接单，仍然是另一回事。","frontmatter":{"title":"Nav2 为什么不会“一窝蜂启动”？拆解 `nav2_lifecycle_manager` 全数据流","description":"Nav2 里有 mapserver、AMCL、plannerserver、controllerserver、btnavigator 等一批服务器。进程启动，只代表它们进入了 ROS graph；参数是否加载成功、插件是否创建完成、Action 是否可以接单，仍然是另一回事。","date":"2026-07-15","section":"一 · 架构与启动","readingTime":8,"source":"2026-07-15/nav2_lifecycle_manager_full_dataflow.md","status":"published","cover":"/article-assets/2026-07-15/nav2_lifecycle_manager_cover.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-lifecycle-manager-full-dataflow"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"Nav2 为什么不会“一窝蜂启动”？拆解 `nav2_lifecycle_manager` 全数据流"}],["meta",{"property":"og:description","content":"Nav2 里有 mapserver、AMCL、plannerserver、controllerserver、btnavigator 等一批服务器。进程启动，只代表它们进入了 ROS graph；参数是否加载成功、插件是否创建完成、Action 是否可以接单，仍然是另一回事。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/nav2/nav2-lifecycle-manager-full-dataflow"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-15/nav2_lifecycle_manager_cover.png"}],["meta",{"property":"article:published_time","content":"2026-07-15"}],["meta",{"name":"twitter:title","content":"Nav2 为什么不会“一窝蜂启动”？拆解 `nav2_lifecycle_manager` 全数据流"}],["meta",{"name":"twitter:description","content":"Nav2 里有 mapserver、AMCL、plannerserver、controllerserver、btnavigator 等一批服务器。进程启动，只代表它们进入了 ROS graph；参数是否加载成功、插件是否创建完成、Action 是否可以接单，仍然是另一回事。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-07-15/nav2_lifecycle_manager_cover.png"}]],"prev":{"text":"Nav2 为什么能边规划边控制？拆解 `nav2_behavior_tree` 调用全数据流","link":"/nav2/nav2-behavior-tree-full-dataflow"},"next":{"text":"一张 PGM 地图怎样进入 Nav2？拆解 `nav2_map_server` 调用全数据流","link":"/nav2/nav2-map-server-full-dataflow"}},"headers":[],"relativePath":"nav2/nav2-lifecycle-manager-full-dataflow.md","filePath":"nav2/nav2-lifecycle-manager-full-dataflow.md","lastUpdated":null}'),h={name:"nav2/nav2-lifecycle-manager-full-dataflow.md"};function u(_,e,g,v,m,b){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="nav2-为什么不会-一窝蜂启动-拆解-nav2-lifecycle-manager-全数据流" tabindex="-1">Nav2 为什么不会“一窝蜂启动”？拆解 <code>nav2_lifecycle_manager</code> 全数据流 <a class="header-anchor" href="#nav2-为什么不会-一窝蜂启动-拆解-nav2-lifecycle-manager-全数据流" aria-label="Permalink to &quot;Nav2 为什么不会“一窝蜂启动”？拆解 `nav2_lifecycle_manager` 全数据流&quot;">​</a></h1><p><img src="'+s+'" alt="nav2_lifecycle_manager 封面"></p><p>Nav2 里有 map_server、AMCL、planner_server、controller_server、bt_navigator 等一批服务器。进程启动，只代表它们进入了 ROS graph；参数是否加载成功、插件是否创建完成、Action 是否可以接单，仍然是另一回事。</p><p><code>nav2_lifecycle_manager</code> 解决的正是这个问题：它把一组 Lifecycle 节点当成一个系统，统一控制启动、暂停、恢复、重置和关闭，并用 Bond 心跳监控节点是否仍然存活。</p><p>这篇文章不逐行翻译源码，而是沿着请求、状态迁移、心跳和故障恢复四条数据流，把它的完整工作过程拆开。</p><h2 id="一、它管理的不是进程-而是-可用状态" tabindex="-1">一、它管理的不是进程，而是“可用状态” <a class="header-anchor" href="#一、它管理的不是进程-而是-可用状态" aria-label="Permalink to &quot;一、它管理的不是进程，而是“可用状态”&quot;">​</a></h2><p>普通 ROS 2 节点启动后通常立即开始工作。Lifecycle 节点不同，它需要经过明确的主状态：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>unconfigured → inactive → active → finalized</span></span></code></pre></div><p><code>unconfigured</code> 表示进程存在，但业务资源尚未配置；<code>inactive</code> 表示参数、插件和通信资源已经准备好，但还不对外工作；<code>active</code> 才表示 Publisher、Action Server 和控制循环真正可用。</p><p>Lifecycle Manager 位于调用方和所有托管节点之间。外部只向管理器发送一条命令，管理器再逐个调用每个节点的 lifecycle 服务。</p><p><img src="'+c+'" alt="Lifecycle Manager 统一状态编排入口"></p><p>它对外暴露两个核心服务：</p><ul><li><code>/&lt;manager&gt;/manage_nodes</code>：类型为 <code>nav2_msgs/srv/ManageLifecycleNodes</code>，接收 STARTUP、RESET、SHUTDOWN、PAUSE、RESUME。</li><li><code>/&lt;manager&gt;/is_active</code>：类型为 <code>std_srvs/srv/Trigger</code>，返回内部的 <code>system_active_</code>。</li></ul><p>注意，<code>is_active</code> 并不会临时遍历所有节点重新查询状态，它返回的是管理器维护的系统标志。因此这个标志是否可靠，取决于所有状态迁移和 Bond 故障处理是否完整执行。</p><h2 id="二、构造阶段已经搭起三条执行链" tabindex="-1">二、构造阶段已经搭起三条执行链 <a class="header-anchor" href="#二、构造阶段已经搭起三条执行链" aria-label="Permalink to &quot;二、构造阶段已经搭起三条执行链&quot;">​</a></h2><p><code>LifecycleManager</code> 本身是普通 <code>rclcpp::Node</code>，既可以作为独立可执行文件运行，也注册成 <code>rclcpp_components</code> 组件。</p><p>构造函数首先读取五个关键参数：</p><ul><li><code>node_names</code>：托管节点列表，也是启动顺序。</li><li><code>autostart</code>：是否创建完客户端后自动执行 STARTUP。</li><li><code>bond_timeout</code>：Bond 心跳超时时间，默认 4 秒；设为 0 会关闭 Bond 监控。</li><li><code>bond_respawn_max_duration</code>：等待崩溃节点恢复的最大窗口，默认 10 秒。</li><li><code>attempt_respawn_reconnection</code>：是否尝试在节点重生后自动拉起整组系统。</li></ul><p><img src="'+o+'" alt="构造阶段与线程模型"></p><p>这里形成三条链：</p><h3 id="_2-1-命令链" tabindex="-1">2.1 命令链 <a class="header-anchor" href="#_2-1-命令链" aria-label="Permalink to &quot;2.1 命令链&quot;">​</a></h3><p><code>manage_nodes</code> 收到请求后进入 <code>managerCallback()</code>，再分派给 <code>startup()</code>、<code>reset()</code>、<code>shutdown()</code>、<code>pause()</code> 或 <code>resume()</code>。</p><h3 id="_2-2-节点控制链" tabindex="-1">2.2 节点控制链 <a class="header-anchor" href="#_2-2-节点控制链" aria-label="Permalink to &quot;2.2 节点控制链&quot;">​</a></h3><p>一个 0 秒 wall timer 延迟创建 <code>LifecycleServiceClient</code>，每个 <code>node_names</code> 元素对应一个客户端，负责调用该节点的 <code>change_state</code> 和 <code>get_state</code>。</p><h3 id="_2-3-健康链" tabindex="-1">2.3 健康链 <a class="header-anchor" href="#_2-3-健康链" aria-label="Permalink to &quot;2.3 健康链&quot;">​</a></h3><p><code>DiagnosticUpdater</code> 持续发布 <code>Nav2 Health</code>，Bond timer 在系统 active 后检查各节点心跳。</p><p>两个管理服务被放入 <code>MutuallyExclusive</code> callback group，并由独立的 <code>SingleThreadedExecutor</code> 和 <code>NodeThread</code> 执行。这意味着同一个管理器不会同时处理两条状态命令，避免 STARTUP 与 RESET 之类的操作交叉执行。</p><h2 id="三、startup-不是逐节点-配置后立刻激活" tabindex="-1">三、STARTUP 不是逐节点“配置后立刻激活” <a class="header-anchor" href="#三、startup-不是逐节点-配置后立刻激活" aria-label="Permalink to &quot;三、STARTUP 不是逐节点“配置后立刻激活”&quot;">​</a></h2><p>STARTUP 的真实顺序很重要。源码不是让 N1 configure、N1 activate，然后处理 N2；而是分成两个完整阶段。</p><h3 id="_3-1-全量-configure" tabindex="-1">3.1 全量 Configure <a class="header-anchor" href="#_3-1-全量-configure" aria-label="Permalink to &quot;3.1 全量 Configure&quot;">​</a></h3><p><code>N1 configure → N2 configure → … → Nn configure</code>。</p><h3 id="_3-2-全量-activate" tabindex="-1">3.2 全量 Activate <a class="header-anchor" href="#_3-2-全量-activate" aria-label="Permalink to &quot;3.2 全量 Activate&quot;">​</a></h3><p><code>N1 activate → N2 activate → … → Nn activate</code>。</p><p><img src="'+l+`" alt="STARTUP 顺序与状态核验"></p><h3 id="_3-3-核验单次状态迁移" tabindex="-1">3.3 核验单次状态迁移 <a class="header-anchor" href="#_3-3-核验单次状态迁移" aria-label="Permalink to &quot;3.3 核验单次状态迁移&quot;">​</a></h3><p>每次迁移都包含两次判断。</p><h4 id="_3-3-1-调用状态变更服务" tabindex="-1">3.3.1 调用状态变更服务 <a class="header-anchor" href="#_3-3-1-调用状态变更服务" aria-label="Permalink to &quot;3.3.1 调用状态变更服务&quot;">​</a></h4><p>调用 <code>change_state(transition)</code> 并检查服务返回。</p><h4 id="_3-3-2-核验最终主状态" tabindex="-1">3.3.2 核验最终主状态 <a class="header-anchor" href="#_3-3-2-核验最终主状态" aria-label="Permalink to &quot;3.3.2 核验最终主状态&quot;">​</a></h4><p>调用 <code>get_state()</code>，确认节点确实到达 <code>transition_state_map_</code> 记录的目标主状态。服务调用成功但最终状态不对，同样会被判为失败。</p><h3 id="_3-4-建立-bond-与系统状态" tabindex="-1">3.4 建立 Bond 与系统状态 <a class="header-anchor" href="#_3-4-建立-bond-与系统状态" aria-label="Permalink to &quot;3.4 建立 Bond 与系统状态&quot;">​</a></h3><p>当节点进入 active，管理器会为它创建 Bond：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>topic：bond</span></span>
<span class="line"><span>heartbeat period：0.10 s</span></span>
<span class="line"><span>heartbeat timeout：bond_timeout</span></span>
<span class="line"><span>首次建链等待上限：bond_timeout / 2</span></span></code></pre></div><p>只有全部节点 configure、activate 且 Bond 建立成功，管理器才执行：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>system_active_ = true</span></span>
<span class="line"><span>createBondTimer()</span></span></code></pre></div><p>任意一步失败，STARTUP 立即返回 false，并打印 <code>Failed to bring up all requested nodes</code>。它不会把“部分节点 active”包装成成功。</p><h2 id="四、为什么启动正序-停机必须逆序" tabindex="-1">四、为什么启动正序，停机必须逆序 <a class="header-anchor" href="#四、为什么启动正序-停机必须逆序" aria-label="Permalink to &quot;四、为什么启动正序，停机必须逆序&quot;">​</a></h2><p><code>node_names</code> 不只是名单，它隐含依赖顺序。典型导航链可以写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>controller_server → planner_server → behavior_server → bt_navigator</span></span></code></pre></div><p>启动时按正序处理，使基础服务器先准备；停机时按逆序处理，让上层调用者先停止接单，再关闭下层能力。</p><p><img src="`+r+'" alt="五类管理命令与迁移方向"></p><p>五类命令的语义分别是：</p><h3 id="_4-1-startup" tabindex="-1">4.1 STARTUP <a class="header-anchor" href="#_4-1-startup" aria-label="Permalink to &quot;4.1 STARTUP&quot;">​</a></h3><p>正序 CONFIGURE，再正序 ACTIVATE，最后建立系统健康监控。</p><h3 id="_4-2-pause" tabindex="-1">4.2 PAUSE <a class="header-anchor" href="#_4-2-pause" aria-label="Permalink to &quot;4.2 PAUSE&quot;">​</a></h3><p>逆序 DEACTIVATE，节点保留已配置资源，系统可以快速恢复。</p><h3 id="_4-3-resume" tabindex="-1">4.3 RESUME <a class="header-anchor" href="#_4-3-resume" aria-label="Permalink to &quot;4.3 RESUME&quot;">​</a></h3><p>正序 ACTIVATE，重新建立每个节点的 Bond。</p><h3 id="_4-4-reset" tabindex="-1">4.4 RESET <a class="header-anchor" href="#_4-4-reset" aria-label="Permalink to &quot;4.4 RESET&quot;">​</a></h3><p>逆序 DEACTIVATE，再逆序 CLEANUP，最终回到 unconfigured，但进程仍在。</p><h3 id="_4-5-shutdown" tabindex="-1">4.5 SHUTDOWN <a class="header-anchor" href="#_4-5-shutdown" aria-label="Permalink to &quot;4.5 SHUTDOWN&quot;">​</a></h3><p>逆序 DEACTIVATE、CLEANUP、UNCONFIGURED_SHUTDOWN，最终进入 finalized，并销毁 lifecycle 客户端。</p><p>因此 PAUSE 和 RESET 不是一回事：PAUSE 保留配置结果，RESET 会释放插件、地图、代价地图等在 configure 阶段创建的业务资源。SHUTDOWN 更进一步，使 Lifecycle 节点到达终态，不能再从 finalized 重新 configure。</p><h2 id="五、bond-不是-在线状态图标-而是故障触发器" tabindex="-1">五、Bond 不是“在线状态图标”，而是故障触发器 <a class="header-anchor" href="#五、bond-不是-在线状态图标-而是故障触发器" aria-label="Permalink to &quot;五、Bond 不是“在线状态图标”，而是故障触发器&quot;">​</a></h2><p>系统 active 后，管理器每 200 毫秒遍历 <code>bond_map_</code>。只要一个 Bond 的 <code>isBroken()</code> 返回 true，就认为整套 Nav2 已经失去一致性。</p><p><img src="'+p+`" alt="Bond 故障后的整组硬重置"></p><p>故障处理不是只重启掉线节点，而是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单节点 Bond 断裂</span></span>
<span class="line"><span>→ system_active_ = false</span></span>
<span class="line"><span>→ reset(true)</span></span>
<span class="line"><span>→ 整组节点逆序 deactivate + cleanup</span></span>
<span class="line"><span>→ 清空 bond_map_</span></span></code></pre></div><p>这里的 <code>hard_reset=true</code> 很关键。普通 RESET 遇到一个节点迁移失败会立即中止；硬重置会继续处理其余仍存活节点。因为崩溃节点已经无法响应 lifecycle 服务，如果仍采用普通模式，系统会卡在第一个失败点，其他节点继续 active，留下更危险的半工作状态。</p><p>这体现了 Lifecycle Manager 的核心取舍：一致性优先于局部可用性。规划器崩溃后，即使 controller_server 还活着，也不再把整套导航标记为 active。</p><h2 id="六、节点重生后-管理器如何自动恢复" tabindex="-1">六、节点重生后，管理器如何自动恢复 <a class="header-anchor" href="#六、节点重生后-管理器如何自动恢复" aria-label="Permalink to &quot;六、节点重生后，管理器如何自动恢复&quot;">​</a></h2><h3 id="_6-1-启动-respawn-timer" tabindex="-1">6.1 启动 Respawn Timer <a class="header-anchor" href="#_6-1-启动-respawn-timer" aria-label="Permalink to &quot;6.1 启动 Respawn Timer&quot;">​</a></h3><p>如果 <code>attempt_respawn_reconnection=true</code>，Bond 故障后会启动一个 1 秒周期的 respawn timer。</p><p><img src="`+d+`" alt="节点重生后的自动恢复窗口"></p><h3 id="_6-2-检查-lifecycle-服务" tabindex="-1">6.2 检查 Lifecycle 服务 <a class="header-anchor" href="#_6-2-检查-lifecycle-服务" aria-label="Permalink to &quot;6.2 检查 Lifecycle 服务&quot;">​</a></h3><p>每轮检查依次对所有 <code>node_names</code> 调用 <code>get_state()</code>。这里关心的不是节点当前处于 active 还是 unconfigured，而是 lifecycle 服务是否重新可访问。</p><h3 id="_6-3-重新启动整组节点" tabindex="-1">6.3 重新启动整组节点 <a class="header-anchor" href="#_6-3-重新启动整组节点" aria-label="Permalink to &quot;6.3 重新启动整组节点&quot;">​</a></h3><p>当所有服务都恢复，管理器停止 respawn timer，清零恢复起始时间，并重新调用 <code>startup()</code>。整组节点再次走完 configure、activate 和 Bond 建链流程。</p><h3 id="_6-4-超时后停止自动恢复" tabindex="-1">6.4 超时后停止自动恢复 <a class="header-anchor" href="#_6-4-超时后停止自动恢复" aria-label="Permalink to &quot;6.4 超时后停止自动恢复&quot;">​</a></h3><p>如果超过 <code>bond_respawn_max_duration</code> 仍未全部恢复，自动恢复停止，系统保持 inactive，等待外部运维处理。</p><h3 id="_6-5-避免并发恢复" tabindex="-1">6.5 避免并发恢复 <a class="header-anchor" href="#_6-5-避免并发恢复" aria-label="Permalink to &quot;6.5 避免并发恢复&quot;">​</a></h3><p>如果外部已经把系统重新激活、ROS 正在退出，或 <code>node_names</code> 已清空，自动恢复会立即取消，避免与外部命令争抢状态机。</p><h2 id="七、lifecyclemanagerclient-做了什么" tabindex="-1">七、LifecycleManagerClient 做了什么 <a class="header-anchor" href="#七、lifecyclemanagerclient-做了什么" aria-label="Permalink to &quot;七、LifecycleManagerClient 做了什么&quot;">​</a></h2><p><code>LifecycleManagerClient</code> 是 RViz2 或业务程序使用的轻量封装。构造时只需要管理器名称，例如：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">LifecycleManagerClient</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> client</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;lifecycle_manager_navigation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">parent_node</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>它会拼出两个服务名：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lifecycle_manager_navigation/manage_nodes</span></span>
<span class="line"><span>lifecycle_manager_navigation/is_active</span></span></code></pre></div><p><code>startup()</code>、<code>shutdown()</code>、<code>pause()</code>、<code>resume()</code> 和 <code>reset()</code> 最终都进入同一个 <code>callService()</code>，区别只是请求中的 command 数值。</p><p><code>is_active()</code> 有三种结果：ACTIVE、INACTIVE、TIMEOUT。服务不存在、等待超时或调用抛出运行时异常都会归为 TIMEOUT；服务正常返回后，再根据 response.success 区分 ACTIVE 与 INACTIVE。</p><h2 id="八、结合真实报错-应该怎样定位" tabindex="-1">八、结合真实报错，应该怎样定位 <a class="header-anchor" href="#八、结合真实报错-应该怎样定位" aria-label="Permalink to &quot;八、结合真实报错，应该怎样定位&quot;">​</a></h2><p>看到下面的日志：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Failed to change state for node: map_server</span></span>
<span class="line"><span>Failed to bring up all requested nodes. Aborting bringup.</span></span></code></pre></div><p>第二行只是汇总结论，第一行也不是最底层原因。真正应该向前找的是目标节点自己的 configure／activate 日志，以及它当时的 lifecycle 主状态。</p><p>常见根因有四类：</p><ul><li>参数、地图或插件在 <code>on_configure()</code> 中加载失败。</li><li>节点当前状态不允许目标 transition，例如对 finalized 节点再次 configure。</li><li>服务同名冲突，请求命中了旧实例。</li><li>节点 active 后没有正确创建 Bond，管理器等待建链失败。</li></ul><p>排障时先执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lifecycle</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /map_server</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manage_nodes</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ros2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>如果使用仿真，还要确认 <code>/clock</code> 只有一个发布者。多个时钟源会让 TF buffer 和 RViz2 反复检测到时间倒退，看起来像 lifecycle 或显示故障，实际是系统时间基准已经不一致。</p><h2 id="九、读完源码后最值得记住的六点" tabindex="-1">九、读完源码后最值得记住的六点 <a class="header-anchor" href="#九、读完源码后最值得记住的六点" aria-label="Permalink to &quot;九、读完源码后最值得记住的六点&quot;">​</a></h2><h3 id="_9-1-管理整组节点的可用状态" tabindex="-1">9.1 管理整组节点的可用状态 <a class="header-anchor" href="#_9-1-管理整组节点的可用状态" aria-label="Permalink to &quot;9.1 管理整组节点的可用状态&quot;">​</a></h3><p>Lifecycle Manager 管的是整组节点的“可用状态”，不是简单拉起进程。</p><h3 id="_9-2-startup-分为两个完整阶段" tabindex="-1">9.2 STARTUP 分为两个完整阶段 <a class="header-anchor" href="#_9-2-startup-分为两个完整阶段" aria-label="Permalink to &quot;9.2 STARTUP 分为两个完整阶段&quot;">​</a></h3><p>STARTUP 是先全量 configure，再全量 activate，不是逐节点一步到位。</p><h3 id="_9-3-启停顺序表达依赖关系" tabindex="-1">9.3 启停顺序表达依赖关系 <a class="header-anchor" href="#_9-3-启停顺序表达依赖关系" aria-label="Permalink to &quot;9.3 启停顺序表达依赖关系&quot;">​</a></h3><p>启动按 <code>node_names</code> 正序，停止和清理按逆序，列表顺序就是依赖设计。</p><h3 id="_9-4-同时检查服务与最终状态" tabindex="-1">9.4 同时检查服务与最终状态 <a class="header-anchor" href="#_9-4-同时检查服务与最终状态" aria-label="Permalink to &quot;9.4 同时检查服务与最终状态&quot;">​</a></h3><p>每次迁移既检查服务返回，也核验最终主状态。</p><h3 id="_9-5-bond-故障触发整组硬重置" tabindex="-1">9.5 Bond 故障触发整组硬重置 <a class="header-anchor" href="#_9-5-bond-故障触发整组硬重置" aria-label="Permalink to &quot;9.5 Bond 故障触发整组硬重置&quot;">​</a></h3><p>任何 Bond 故障都会让整组系统硬重置，以一致性换取安全。</p><h3 id="_9-6-全部服务恢复后才重新-startup" tabindex="-1">9.6 全部服务恢复后才重新 STARTUP <a class="header-anchor" href="#_9-6-全部服务恢复后才重新-startup" aria-label="Permalink to &quot;9.6 全部服务恢复后才重新 STARTUP&quot;">​</a></h3><p>respawn 恢复只有在全部 lifecycle 服务重新出现后才会重新 STARTUP。</p><p><code>nav2_lifecycle_manager</code> 的代码量不算大，但它决定了 Nav2 是一堆“进程都在”的节点，还是一套状态一致、可监控、可恢复的导航系统。</p>`,112)])])}const y=a(h,[["render",u]]);export{k as __pageData,y as default};
